class Blitz {

	constructor(clr) {
		this.n = 6;
		this.top = this.n - 1;

		this.l = Array(this.n);
		this.a = Array(this.n);

		this.c = clr; // random(127,256);

		this.l[this.n - 1] = random(100, width / sqrt(2));
		this.a[this.n - 1] = random(TWO_PI);
		for (i = this.n - 2; i >= 0; i--) {
			this.l[i] = this.l[i + 1] - random(75);
			this.a[i] = this.a[i + 1] + random(-0.3, 0.3);
		}
	}

	show() {
		for (i = this.n - 2; i >= 0; i--) {
			stroke(this.c);

			if (this.a[(this.top + i + 2) % this.n] < this.a[(this.top + i + 1) % this.n]) {
				arc(0, 0, 2 * this.l[(this.top + i + 1) % this.n], 2 * this.l[(this.top + i + 1) % this.n], this.a[(this.top + i + 2) % this.n], this.a[(this.top + i + 1) % this.n]);
			} else {
				arc(0, 0, 2 * this.l[(this.top + i + 1) % this.n], 2 * this.l[(this.top + i + 1) % this.n], this.a[(this.top + i + 1) % this.n], this.a[(this.top + i + 2) % this.n]);
			}
			line(this.l[(this.top + i + 1) % this.n] * cos(this.a[(this.top + i + 2) % this.n]), this.l[(this.top + i + 1) % this.n] * sin(this.a[(this.top + i + 2) % this.n]), this.l[(this.top + i + 2) % this.n] * cos(this.a[(this.top + i + 2) % this.n]), this.l[(this.top + i + 2) % this.n] * sin(this.a[(this.top + i + 2) % this.n]));
		}

		this.l[this.top] = this.l[(this.top + 1) % this.n] - random(75);

		if (this.l[this.top] < 0) {
			this.l[this.n - 1] = width / sqrt(2);
			this.a[this.n - 1] = random(TWO_PI);
			for (i = this.n - 2; i >= 0; i--) {
				this.l[i] = this.l[i + 1] - random(75);
				this.a[i] = this.a[i + 1] + random(-0.3, 0.3);
			}
			this.top = this.n - 1;

		} else {

			this.a[this.top] = this.a[(this.top + 1) % this.n] + random(-0.3, 0.3);

			this.top = (this.top - 1);
			if (this.top < 0) this.top = this.n - 1;
		}

	}

}

